	if r.RecordType == "symbol" {
		r.FilePath = path
		r.Path = ""
		return
	}
	if r.FilePath != "" {
		r.FilePath = path
		return
	}
	r.Path = path
}

func validateSemanticRecordPath(record *semanticRecord) error {
	switch record.RecordType {
	case "file", "symbol":
	default:
		return nil
	}
	path := record.semanticPath()
	if path == "" {
		return nil
	}
	clean, err := validateSemanticProviderPath(path)
	if err != nil {
